class Solution:
    def climbStairs(self, n: int) -> int:
        dp = [0] * (n + 1)
        dp[0] = dp[1] = 1
        for i in range(2, n + 1):
            dp[i] = dp[i - 1] + dp[i - 2]   # 最后一步跨 1 阶或 2 阶
        return dp[n]

class Solution:
    def climbStairs(self, n: int) -> int:
        a, b = 1, 1                         # dp[i-1], dp[i]
        for _ in range(n - 1):
            a, b = b, a + b
        return b

